begin;
select no_plan();
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
create function pg_temp.ready_fixture(n integer) returns uuid language plpgsql as $$
declare t uuid:='00000000-0000-4000-8000-000000000102';c uuid;j public.job_runs;r uuid;p uuid;row public.campaigns;
begin
 c:=public.save_campaign(t,null,0,jsonb_build_object('title','Original synthetic fidelity '||n,'goal','Educational note','channel','email_text','planned_at',date_trunc('milliseconds',now()+interval '100 days'+n*interval '7 days'),'audience_id','00000000-0000-4000-8000-000000000502'));
 update public.campaigns set synthetic=true where id=c;
 perform public.approve_calendar(t,c,1);
 perform public.save_copy(t,c,1,'{"subject":"Original synthetic note","preheader":"Fixture fidelity","body":"An original educational note for this fictional studio.","cta":"Explore","url":"https://north-studio.example/collection"}');
 perform public.approve_copy(t,c,2);
 perform public.enqueue_render(t,c,2,2);
 select * into j from public.claim_job(t);
 r:=public.finish_render_job(j.id,j.lease_token,'{"synthetic":true,"strips":[]}');
 perform public.review_render(t,r,3,'approved','whole_design','Owner approved exact synthetic version');
 select * into row from public.campaigns where id=c;
 p:=public.create_delivery_package(t,c,row.delivery_revision,'{"senderName":"Synthetic North","senderEmail":"studio@north-studio.example","address":"42 Fictional Road, Synthetic Town","unsubscribeUrl":"https://north-studio.example/unsubscribe","privacyUrl":"https://north-studio.example/privacy"}');
 return c;
end $$;
create function pg_temp.schedule_fixture(c uuid) returns uuid language plpgsql as $$
declare t uuid:='00000000-0000-4000-8000-000000000102';p public.delivery_packages;j public.job_runs;
begin
 select * into p from public.delivery_packages where campaign_id=c order by revision desc limit 1;
 perform public.enqueue_delivery(t,p.id,p.revision);
 select * into j from public.claim_job(t);
 perform public.fixture_delivery_command(j.id,j.lease_token,'reconcile');
 perform public.fixture_delivery_command(j.id,j.lease_token,'prepare');
 perform public.fixture_delivery_command(j.id,j.lease_token,'schedule');
 perform public.finish_delivery_job(j.id,j.lease_token);
 return j.id;
end $$;
-- Actual domain package -> queue -> persisted provider; 100 consecutive distinct sends.
do $$declare c uuid;i integer;begin for i in 1..100 loop c:=pg_temp.ready_fixture(i);perform pg_temp.schedule_fixture(c);end loop;end $$;
select is((select count(*) from public.fixture_deliveries),100::bigint,'100 consecutive persisted fixture pushes accepted');
select ok(not exists(select 1 from public.fixture_deliveries f join public.delivery_packages p on p.id=f.package_id where f.snapshot is distinct from p.snapshot or f.state<>'scheduled' or f.scheduled_at is distinct from (p.snapshot->>'scheduledAt')::timestamptz),'all 100 audience/content/HTML/link/footer/time snapshots match exactly');
select is((select count(distinct idempotency_key) from public.fixture_deliveries),100::bigint,'100 pushes have distinct deterministic intent keys');
select is((select count(*) from public.segment_registry where tenant_id='00000000-0000-4000-8000-000000000102'),3::bigint,'account registry contains engaged, purchasers and required suppression');
select set_config('test.c',pg_temp.ready_fixture(101)::text,true);
select set_config('test.p',(select id::text from public.delivery_packages where campaign_id=current_setting('test.c')::uuid),true);
select set_config('test.rev',(select revision::text from public.delivery_packages where id=current_setting('test.p')::uuid),true);
set local role authenticated;
select public.set_fixture_fault('00000000-0000-4000-8000-000000000102',current_setting('test.c')::uuid,'timeout_after_success');
select set_config('test.j',public.enqueue_delivery('00000000-0000-4000-8000-000000000102',current_setting('test.p')::uuid,current_setting('test.rev')::integer)::text,true);
select is(public.enqueue_delivery('00000000-0000-4000-8000-000000000102',current_setting('test.p')::uuid,current_setting('test.rev')::integer)::text,current_setting('test.j'),'duplicate enqueue returns same intent');
select set_config('test.lease',(select lease_token::text from public.claim_job('00000000-0000-4000-8000-000000000102')),true);
