select public.fail_job(current_setting('test.j')::uuid,current_setting('test.lease')::uuid,'unknown_outcome');
select is((select delivery_state from public.campaigns where id=current_setting('test.c')::uuid),'reconciling','timeout never marks unconfirmed delivery scheduled');
select public.retry_fixture_job('00000000-0000-4000-8000-000000000102',current_setting('test.j')::uuid);
select set_config('test.lease',(select lease_token::text from public.claim_job('00000000-0000-4000-8000-000000000102')),true);
select is(public.fixture_delivery_command(current_setting('test.j')::uuid,current_setting('test.lease')::uuid,'reconcile')->>'outcome','found','retry reconciles prior success');
select public.finish_delivery_job(current_setting('test.j')::uuid,current_setting('test.lease')::uuid);
select is((select count(*) from public.fixture_deliveries where package_id=current_setting('test.p')::uuid),1::bigint,'timeout reconciliation never creates duplicate remote');
select set_config('test.remote',(select id::text from public.fixture_deliveries where package_id=current_setting('test.p')::uuid),true);
select set_config('test.reschedule',public.request_reschedule('00000000-0000-4000-8000-000000000102',current_setting('test.c')::uuid,current_setting('test.rev')::integer,(select planned_at+interval '1 hour' from public.campaigns where id=current_setting('test.c')::uuid))::text,true);
select set_config('test.lease',(select lease_token::text from public.claim_job('00000000-0000-4000-8000-000000000102')),true);
select public.fixture_delivery_command(current_setting('test.reschedule')::uuid,current_setting('test.lease')::uuid,'reconcile');
select lives_ok($$select public.fixture_delivery_command(current_setting('test.reschedule')::uuid,current_setting('test.lease')::uuid,'reschedule')$$,'reschedule updates same provider identity');
select public.finish_delivery_job(current_setting('test.reschedule')::uuid,current_setting('test.lease')::uuid);
select is((select f.id::text from public.fixture_deliveries f join public.delivery_packages p on p.id=f.package_id where p.campaign_id=current_setting('test.c')::uuid),current_setting('test.remote'),'reschedule preserves remote ID');
