select is((select delivery_state from public.campaigns where id=current_setting('test.c')::uuid),'scheduled','cancellation failure cannot imply cancelled');
select throws_ok($$select public.retry_fixture_job('00000000-0000-4000-8000-000000000102',current_setting('test.cancel')::uuid)$$,'23514',null,'permanent unresolved fault cannot blindly retry');
select public.set_fixture_fault('00000000-0000-4000-8000-000000000102',current_setting('test.c')::uuid,'none');
select public.retry_fixture_job('00000000-0000-4000-8000-000000000102',current_setting('test.cancel')::uuid);
select set_config('test.lease',(select lease_token::text from public.claim_job('00000000-0000-4000-8000-000000000102')),true);
select public.fixture_delivery_command(current_setting('test.cancel')::uuid,current_setting('test.lease')::uuid,'reconcile');
select public.fixture_delivery_command(current_setting('test.cancel')::uuid,current_setting('test.lease')::uuid,'cancel');
