set local role authenticated;
select throws_ok($$select public.confirm_fixture_sent('00000000-0000-4000-8000-000000000102',current_setting('test.sentremote')::uuid,now())$$,'23514',null,'send requires explicit simulated clock at scheduled date');
select public.confirm_fixture_sent('00000000-0000-4000-8000-000000000102',current_setting('test.sentremote')::uuid,(select planned_at from public.campaigns where id=current_setting('test.sent')::uuid));
select public.confirm_fixture_sent('00000000-0000-4000-8000-000000000102',current_setting('test.sentremote')::uuid,(select planned_at from public.campaigns where id=current_setting('test.sent')::uuid));
